using System;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[Serializable]
public class OmenLogicActionFace
{
	[AllowNesting]
	public OmenLogic OmenLogic;

	[AllowNesting]
	public ActionFace ActionFace;

	public void ActivateOmen(GameObject target = null, GameObject source = null, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		OmenLogic.ActivateOmen(ActionFace.BattleAction, ActionFace.ActionValue, target, source, corruptionPurifyModifierEnum, playSFX);
	}

	public string GetActionDescription()
	{
		return ActionFace.BattleAction.GetActionDescription(ActionFace.ActionValue);
	}

	public void ActivateOmen(int amount, GameObject target = null, GameObject source = null, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		OmenLogic.ActivateOmen(ActionFace.BattleAction, amount, target, source, corruptionPurifyModifierEnum, playSFX);
	}
}
